import { Router, type Request, type Response } from 'express';

export interface BookmarkInput {
  url: string;
  title?: string;
  tags?: string[];
}

export const bookmarksRouter = Router();

function isBookmarkInput(value: unknown): value is BookmarkInput {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  const candidate = value as Record<string, unknown>;

  if (typeof candidate.url !== 'string') {
    return false;
  }

  if (candidate.title !== undefined && typeof candidate.title !== 'string') {
    return false;
  }

  if (candidate.tags !== undefined) {
    if (!Array.isArray(candidate.tags) || !candidate.tags.every((tag): tag is string => typeof tag === 'string')) {
      return false;
    }
  }

  return true;
}

bookmarksRouter.post('/', (req: Request, res: Response) => {
  const body: unknown = req.body;

  if (!isBookmarkInput(body)) {
    res.status(400).json({ error: 'Invalid bookmark payload' });
    return;
  }

  const { url, title, tags } = body;

  res.status(201).json({
    url,
    title,
    tags,
  });
});

export default bookmarksRouter;

