import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface UpdateBookmarkDTO {
  title?: string;
  tags?: string[];
}

export interface PaginationMeta {
  page: number;
  limit: number;
  total: number;
  totalPages: number;
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: PaginationMeta;
}

export class DuplicateBookmarkError extends Error {
  constructor(message = 'Bookmark with this URL already exists') {
    super(message);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private bookmarks: Map<string, Bookmark> = new Map();

  create(data: CreateBookmarkDTO): Bookmark {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === data.url) {
        throw new DuplicateBookmarkError(`Bookmark with URL "${data.url}" already exists`);
      }
    }

    const id = randomUUID();
    const bookmark: Bookmark = {
      id,
      url: data.url,
      title: data.title,
      tags: data.tags ? [...data.tags] : undefined,
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const offset = (page - 1) * limit;
    const data = all.slice(offset, offset + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  update(id: string, data: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      title: data.title !== undefined ? data.title : existing.title,
      tags: data.tags !== undefined ? [...data.tags] : existing.tags,
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

import { Router, type Request, type Response, type NextFunction } from 'express';
import { z } from 'zod';
import { bookmarkService, DuplicateBookmarkError } from '../services/bookmark-service.js';

export const createBookmarkSchema = z.object({
  url: z.string().url().max(2048),
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type CreateBookmarkInput = z.infer<typeof createBookmarkSchema>;

export const updateBookmarkSchema = z.object({
  title: z.string().max(200).optional(),
  tags: z.array(z.string().max(50)).max(10).optional(),
});

export type UpdateBookmarkInput = z.infer<typeof updateBookmarkSchema>;

export function isCreateBookmarkInput(value: unknown): value is CreateBookmarkInput {
  return createBookmarkSchema.safeParse(value).success;
}

function getQueryString(value: unknown): string | undefined {
  if (typeof value === 'string') {
    return value;
  }
  if (Array.isArray(value) && typeof value[0] === 'string') {
    return value[0];
  }
  return undefined;
}

export function parsePaginationParams(query: Record<string, unknown>): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  const rawPage = getQueryString(query.page);
  if (rawPage !== undefined) {
    const parsed = parseInt(rawPage, 10);
    if (!Number.isNaN(parsed)) {
      page = Math.max(1, parsed);
    }
  }

  const rawLimit = getQueryString(query.limit);
  if (rawLimit !== undefined) {
    const parsed = parseInt(rawLimit, 10);
    if (!Number.isNaN(parsed)) {
      limit = Math.min(100, Math.max(1, parsed));
    }
  }

  return { page, limit };
}

export const bookmarksRouter = Router();

bookmarksRouter.get('/', (req: Request, res: Response) => {
  const query = req.query as Record<string, unknown>;
  const { page, limit } = parsePaginationParams(query);
  const paginatedResult = bookmarkService.getPaginated(page, limit);
  res.status(200).json(paginatedResult);
});

bookmarksRouter.get('/:id', (req: Request, res: Response) => {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const bookmark = bookmarkService.getById(id);

  if (!bookmark) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(200).json(bookmark);
});

bookmarksRouter.post('/', (req: Request, res: Response, next: NextFunction) => {
  const body: unknown = req.body;
  const result = createBookmarkSchema.safeParse(body);

  if (!result.success) {
    next(result.error);
    return;
  }

  try {
    const created = bookmarkService.create(result.data);
    res.status(201).json(created);
  } catch (err: unknown) {
    if (err instanceof DuplicateBookmarkError) {
      res.status(409).json({ error: err.message });
      return;
    }
    next(err);
  }
});

bookmarksRouter.patch('/:id', (req: Request, res: Response, next: NextFunction) => {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const body: unknown = req.body;
  if (typeof body === 'object' && body !== null && 'url' in body && (body as { url: unknown }).url !== undefined) {
    res.status(400).json({ error: 'URL is immutable and cannot be updated' });
    return;
  }

  const result = updateBookmarkSchema.safeParse(body);
  if (!result.success) {
    next(result.error);
    return;
  }

  const updated = bookmarkService.update(id, result.data);
  if (!updated) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(200).json(updated);
});

bookmarksRouter.delete('/:id', (req: Request, res: Response) => {
  const rawId = req.params.id;
  const id = typeof rawId === 'string' ? rawId : undefined;

  if (!id) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  const deleted = bookmarkService.delete(id);
  if (!deleted) {
    res.status(404).json({ error: 'Bookmark not found' });
    return;
  }

  res.status(204).send();
});

export default bookmarksRouter;

import { describe, it, expect, beforeEach } from 'vitest';
import request from 'supertest';
import { app } from '../src/app.js';
import { bookmarkService } from '../src/services/bookmark-service.js';
import { parsePaginationParams } from '../src/routes/bookmarks.js';

describe('Pagination Edge Cases and Behavior', () => {
  describe('parsePaginationParams unit tests', () => {
    it('should clamp page 0 to 1', () => {
      const result = parsePaginationParams({ page: '0' });
      expect(result.page).toBe(1);
      expect(result.limit).toBe(20);
    });

    it('should clamp negative page to 1', () => {
      const result = parsePaginationParams({ page: '-5' });
      expect(result.page).toBe(1);
    });

    it('should clamp negative limit to 1', () => {
      const result = parsePaginationParams({ limit: '-10' });
      expect(result.limit).toBe(1);
    });

    it('should cap limit > 100 at 100', () => {
      const result = parsePaginationParams({ limit: '250' });
      expect(result.limit).toBe(100);
    });

    it('should use default values for non-numeric values', () => {
      const result = parsePaginationParams({ page: 'not-a-number', limit: 'invalid' });
      expect(result.page).toBe(1);
      expect(result.limit).toBe(20);
    });
  });

  describe('GET /api/v1/bookmarks pagination integration tests', () => {
    beforeEach(() => {
      bookmarkService.clear();
      for (let i = 1; i <= 25; i++) {
        bookmarkService.create({
          url: `https://example.com/item-${i}`,
          title: `Item ${i}`,
        });
      }
    });

    it('should treat page 0 as page 1', async () => {
      const response = await request(app)
        .get('/api/v1/bookmarks?page=0&limit=5')
        .set('Accept', 'application/json');

      expect(response.status).toBe(200);
      const body = response.body as {
        data: unknown[];
        pagination: { page: number; limit: number; total: number; totalPages: number };
      };
      expect(body.pagination.page).toBe(1);
      expect(body.pagination.limit).toBe(5);
      expect(body.pagination.total).toBe(25);
      expect(body.pagination.totalPages).toBe(5);
      expect(body.data.length).toBe(5);
    });

    it('should clamp negative limit to 1', async () => {
      const response = await request(app)
        .get('/api/v1/bookmarks?page=1&limit=-10')
        .set('Accept', 'application/json');

      expect(response.status).toBe(200);
      const body = response.body as {
        data: unknown[];
        pagination: { page: number; limit: number; total: number; totalPages: number };
      };
      expect(body.pagination.page).toBe(1);
      expect(body.pagination.limit).toBe(1);
      expect(body.data.length).toBe(1);
    });

    it('should cap limit > 100 at 100', async () => {
      const response = await request(app)
        .get('/api/v1/bookmarks?page=1&limit=150')
        .set('Accept', 'application/json');

      expect(response.status).toBe(200);
      const body = response.body as {
        data: unknown[];
        pagination: { page: number; limit: number; total: number; totalPages: number };
      };
      expect(body.pagination.page).toBe(1);
      expect(body.pagination.limit).toBe(100);
      expect(body.data.length).toBe(25);
    });

    it('should paginate correctly across pages', async () => {
      const page1Res = await request(app)
        .get('/api/v1/bookmarks?page=1&limit=10')
        .set('Accept', 'application/json');
      const page2Res = await request(app)
        .get('/api/v1/bookmarks?page=2&limit=10')
        .set('Accept', 'application/json');

      expect(page1Res.status).toBe(200);
      expect(page2Res.status).toBe(200);

      const page1 = page1Res.body as {
        data: { id: string }[];
        pagination: { page: number; limit: number; total: number; totalPages: number };
      };
      const page2 = page2Res.body as {
        data: { id: string }[];
        pagination: { page: number; limit: number; total: number; totalPages: number };
      };

      expect(page1.pagination.page).toBe(1);
      expect(page1.data.length).toBe(10);
      expect(page2.pagination.page).toBe(2);
      expect(page2.data.length).toBe(10);

      const page1Ids = new Set(page1.data.map((b) => b.id));
      for (const item of page2.data) {
        expect(page1Ids.has(item.id)).toBe(false);
      }
    });
  });
});

