--- BOOKMARK SERVICE ---
import { randomUUID } from 'node:crypto';

export interface Bookmark {
  id: string;
  url: string;
  title?: string;
  tags?: string[];
  createdAt: string;
}

export interface CreateBookmarkDTO {
  url: string;
  title?: string;
  tags?: string[];
}

export interface UpdateBookmarkDTO {
  title?: string;
  tags?: string[];
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    totalPages: number;
  };
}

export class DuplicateBookmarkError extends Error {
  constructor(url: string) {
    super(`Bookmark with URL already exists: ${url}`);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkNotFoundError extends Error {
  constructor(id: string) {
    super(`Bookmark not found: ${id}`);
    this.name = 'BookmarkNotFoundError';
  }
}

export class BookmarkService {
  private readonly bookmarks: Map<string, Bookmark> = new Map();

  /**
   * Creates a new bookmark with a unique ID and ISO timestamp.
   *
   * @param dto - Data transfer object containing URL, optional title, and optional tags.
   * @returns The newly created bookmark.
   * @throws {DuplicateBookmarkError} If a bookmark with the same URL already exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.create({
   *   url: 'https://example.com',
   *   title: 'Example',
   *   tags: ['web'],
   * });
   * ```
   */
  public create(dto: CreateBookmarkDTO): Bookmark {
    for (const existing of this.bookmarks.values()) {
      if (existing.url === dto.url) {
        throw new DuplicateBookmarkError(dto.url);
      }
    }

    const bookmark: Bookmark = {
      id: randomUUID(),
      url: dto.url,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(bookmark.id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its unique identifier.
   *
   * @param id - The UUID of the bookmark to retrieve.
   * @returns The matching bookmark if found, or undefined if not found.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.getById('123e4567-e89b-12d3-a456-426614174000');
   * ```
   */
  public getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Retrieves all bookmarks sorted in descending order by creation date.
   *
   * @returns An array of all stored bookmarks.
   *
   * @example
   * ```ts
   * const allBookmarks = bookmarkService.getAll();
   * ```
   */
  public getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  /**
   * Retrieves a paginated slice of bookmarks sorted by creation date descending.
   *
   * @param page - Page number (1-indexed).
   * @param limit - Maximum number of bookmarks per page.
   * @returns An object containing the sliced bookmark items and pagination metadata.
   *
   * @example
   * ```ts
   * const result = bookmarkService.getPaginated(1, 20);
   * console.log(result.data, result.pagination.totalPages);
   * ```
   */
  public getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const startIndex = (page - 1) * limit;
    const data = all.slice(startIndex, startIndex + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Deletes a bookmark by its unique identifier.
   *
   * @param id - The UUID of the bookmark to delete.
   * @returns True if a bookmark was deleted, false if no matching bookmark was found.
   *
   * @example
   * ```ts
   * const deleted = bookmarkService.delete('123e4567-e89b-12d3-a456-426614174000');
   * ```
   */
  public delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Updates an existing bookmark's title and/or tags.
   *
   * @param id - The UUID of the bookmark to update.
   * @param dto - Data transfer object containing updated title and/or tags.
   * @returns The updated bookmark if found, or undefined if not found.
   *
   * @example
   * ```ts
   * const updated = bookmarkService.update('123e4567-e89b-12d3-a456-426614174000', {
   *   title: 'Updated Title',
   * });
   * ```
   */
  public update(id: string, dto: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      ...(dto.title !== undefined ? { title: dto.title } : {}),
      ...(dto.tags !== undefined ? { tags: dto.tags } : {}),
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Searches bookmarks by case-insensitive substring match on title or exact match on tags.
   *
   * @param query - The search query term.
   * @returns An array of bookmarks matching either title substring or tag exact match.
   *
   * @example
   * ```ts
   * const matches = bookmarkService.search('typescript');
   * ```
   */
  public search(query: string): Bookmark[] {
    const trimmed = query.trim();
    if (!trimmed) {
      return [];
    }
    const lower = trimmed.toLowerCase();
    return this.getAll().filter((bookmark) => {
      const titleMatch =
        bookmark.title !== undefined &&
        bookmark.title.toLowerCase().includes(lower);
      const tagMatch =
        bookmark.tags !== undefined &&
        bookmark.tags.some(
          (tag) => tag.toLowerCase() === lower || tag === trimmed
        );
      return titleMatch || tagMatch;
    });
  }

  /**
   * Clears all stored bookmarks.
   *
   * @returns Void.
   *
   * @example
   * ```ts
   * bookmarkService.clear();
   * ```
   */
  public clear(): void {
    this.bookmarks.clear();
  }
}

export const bookmarkService = new BookmarkService();

