/**
 * Parses and normalizes pagination parameters from an incoming request query.
 *
 * @param query - The request query object or unknown input.
 * @returns An object containing normalized `page` and `limit`.
 *
 * @example
 * ```ts
 * const { page, limit } = parsePaginationParams(req.query);
 * ```
 */
export function parsePaginationParams(query: unknown): { page: number; limit: number } {
  let page = 1;
  let limit = 20;

  if (typeof query !== 'object' || query === null) {
    return { page, limit };
  }

  const record = query as Record<string, unknown>;

  if (typeof record.page === 'string') {
    const parsed = parseInt(record.page, 10);
    if (!isNaN(parsed)) {
      page = parsed < 1 ? 1 : parsed;
    }
  } else if (typeof record.page === 'number' && !isNaN(record.page)) {
    page = record.page < 1 ? 1 : Math.floor(record.page);
  }

  if (typeof record.limit === 'string') {
    const parsed = parseInt(record.limit, 10);
    if (!isNaN(parsed)) {
      if (parsed < 1) {
        limit = 1;
      } else if (parsed > 100) {
        limit = 100;
      } else {
        limit = parsed;
      }
    }
  } else if (typeof record.limit === 'number' && !isNaN(record.limit)) {
    const parsed = Math.floor(record.limit);
    if (parsed < 1) {
      limit = 1;
    } else if (parsed > 100) {
      limit = 100;
    } else {
      limit = parsed;
    }
  }

  return { page, limit };
}

/**
 * Route handler for GET / - Lists bookmarks with pagination support.
 *
 * @param req - Express request object containing optional page and limit query parameters.
 * @param res - Express response object used to send paginated bookmark results.
