 *
 * @example
 * ```ts
 * bookmarksRouter.get('/', listBookmarksHandler);
 * ```
 */
export function listBookmarksHandler(req: Request, res: Response): void {
  const query: unknown = req.query;
  const { page, limit } = parsePaginationParams(query);
  const result = bookmarkService.getPaginated(page, limit);
  res.status(200).json(result);
}

/**
 * Route handler for GET /search - Searches bookmarks by title or tag.
 *
 * @param req - Express request object containing required search query parameter q.
