 */
export function getBookmarkByIdHandler(req: Request, res: Response): void {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }
  const bookmark = bookmarkService.getById(id);
  if (!bookmark) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(200).json(bookmark);
}

/**
 * Route handler for DELETE /:id - Deletes a bookmark by its ID.
 *
 * @param req - Express request object containing the bookmark ID parameter.
 * @param res - Express response object used to send 204 No Content or 404 response.
 * @returns Void.
 *
 * @example
 * ```ts
 * bookmarksRouter.delete('/:id', deleteBookmarkHandler);
 * ```
 */
export function deleteBookmarkHandler(req: Request, res: Response): void {
  const id = req.params.id;
  if (typeof id !== 'string') {
    res.status(400).json({ error: 'Invalid id parameter' });
    return;
  }
  const deleted = bookmarkService.delete(id);
  if (!deleted) {
    res.status(404).json({ error: `Bookmark not found: ${id}` });
    return;
  }
  res.status(204).send();
}

/**
 * Route handler for PATCH /:id - Updates an existing bookmark's title and/or tags.
 *
 * @param req - Express request object containing the bookmark ID and update payload.
