 */
export function createBookmarkHandler(req: Request, res: Response, next: NextFunction): void {
  try {
    const body: unknown = req.body;
    const data = createBookmarkSchema.parse(body);
    const bookmark = bookmarkService.create(data);
    res.status(201).json(bookmark);
  } catch (error: unknown) {
