  limit: number;
  total: number;
  totalPages: number;
}

export interface PaginatedResult<T> {
  data: T[];
  pagination: PaginationMeta;
}

export class DuplicateBookmarkError extends Error {
  constructor(message = 'Bookmark with this URL already exists') {
    super(message);
    this.name = 'DuplicateBookmarkError';
  }
}

export class BookmarkService {
  private bookmarks: Map<string, Bookmark> = new Map();

  /**
   * Creates a new bookmark with a unique ID and ISO timestamp.
   *
   * @param data - The payload containing the required URL, optional title, and optional tags.
   * @returns The created bookmark record including its generated id and createdAt timestamp.
   * @throws {DuplicateBookmarkError} When a bookmark with the provided URL already exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.create({
   *   url: 'https://example.com',
   *   title: 'Example Domain',
   *   tags: ['web', 'example'],
   * });
   * ```
   */
  public create(data: CreateBookmarkDTO): Bookmark {
    for (const bookmark of this.bookmarks.values()) {
      if (bookmark.url === data.url) {
        throw new DuplicateBookmarkError(`Bookmark with URL "${data.url}" already exists`);
      }
    }

    const id = randomUUID();
    const bookmark: Bookmark = {
      id,
      url: data.url,
      title: data.title,
      tags: data.tags ? [...data.tags] : undefined,
      createdAt: new Date().toISOString(),
    };

    this.bookmarks.set(id, bookmark);
    return bookmark;
  }

  /**
   * Retrieves a bookmark by its unique identifier.
   *
   * @param id - The UUID of the bookmark to look up.
   * @returns The matching Bookmark object if found, or undefined if no record exists.
   *
   * @example
   * ```ts
   * const bookmark = bookmarkService.getById('123e4567-e89b-12d3-a456-426614174000');
   * if (bookmark) {
   *   console.log(bookmark.title);
   * }
   * ```
   */
  public getById(id: string): Bookmark | undefined {
    return this.bookmarks.get(id);
  }

  /**
   * Retrieves all bookmarks sorted by creation timestamp in descending order.
   *
   * @returns An array containing all stored bookmarks ordered newest first.
   *
   * @example
   * ```ts
   * const allBookmarks = bookmarkService.getAll();
   * console.log(`Total bookmarks: ${allBookmarks.length}`);
   * ```
   */
  public getAll(): Bookmark[] {
    return Array.from(this.bookmarks.values()).sort(
      (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
    );
  }

  /**
   * Retrieves a paginated subset of bookmarks sorted by creation timestamp descending.
   *
   * @param page - The 1-based page number to retrieve.
   * @param limit - The maximum number of bookmarks per page.
   * @returns An object containing the data slice and pagination metadata (page, limit, total, totalPages).
   *
   * @example
   * ```ts
   * const result = bookmarkService.getPaginated(1, 20);
   * console.log(result.data, result.pagination.totalPages);
   * ```
   */
  public getPaginated(page: number, limit: number): PaginatedResult<Bookmark> {
    const all = this.getAll();
    const total = all.length;
    const totalPages = Math.ceil(total / limit);
    const offset = (page - 1) * limit;
    const data = all.slice(offset, offset + limit);

    return {
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages,
      },
    };
  }

  /**
   * Partially updates an existing bookmark's title and/or tags.
   *
   * @param id - The UUID of the bookmark to update.
