   * @returns The updated Bookmark if found, or undefined if the bookmark does not exist.
   *
   * @example
   * ```ts
   * const updated = bookmarkService.update('123e4567-e89b-12d3-a456-426614174000', {
   *   title: 'New Title',
   *   tags: ['updated'],
   * });
   * ```
   */
  public update(id: string, data: UpdateBookmarkDTO): Bookmark | undefined {
    const existing = this.bookmarks.get(id);
    if (!existing) {
      return undefined;
    }

    const updated: Bookmark = {
      ...existing,
      title: data.title !== undefined ? data.title : existing.title,
      tags: data.tags !== undefined ? [...data.tags] : existing.tags,
    };

    this.bookmarks.set(id, updated);
    return updated;
  }

  /**
   * Searches bookmarks by case-insensitive title substring or exact tag match.
   *
   * @param query - The search query term.
   * @returns An array of matching bookmarks sorted newest first.
   *
   * @example
   * ```ts
   * const results = bookmarkService.search('typescript');
   * ```
   */
  public search(query: string): Bookmark[] {
    const trimmed = query.trim();
    if (!trimmed) {
      return [];
    }
    const lower = trimmed.toLowerCase();
    return this.getAll().filter((bookmark) => {
      const titleMatch =
        bookmark.title !== undefined &&
        bookmark.title.toLowerCase().includes(lower);
      const tagMatch =
        bookmark.tags !== undefined &&
        bookmark.tags.some(
          (tag) => tag.toLowerCase() === lower || tag === trimmed
        );
      return titleMatch || tagMatch;
    });
  }

  /**
   * Deletes a bookmark by its unique identifier.
   *
   * @param id - The UUID of the bookmark to delete.
   * @returns True if a bookmark was found and deleted; false otherwise.
   *
   * @example
   * ```ts
   * const deleted = bookmarkService.delete('123e4567-e89b-12d3-a456-426614174000');
   * if (deleted) {
   *   console.log('Bookmark removed');
   * }
   * ```
   */
  public delete(id: string): boolean {
    return this.bookmarks.delete(id);
  }

  /**
   * Clears all stored bookmarks from the in-memory store.
   *
   * @returns Void.
   *
   * @example
   * ```ts
   * bookmarkService.clear();
   * ```
   */
  public clear(): void {
    this.bookmarks.clear();
  }
}

